{
  "name": "函数/任意波形发生器",
  "name_en": "Function / Arbitrary Waveform Generator",
  "manufacturer": "Agilent",
  "description": "这是一台台式函数/任意波形发生器，用于输出可控的正弦波等测试信号，并可进行触发与突发输出设置。它常用于电子电路调试、仪器联调、激励信号注入和实验室通用信号源应用。",
  "description_en": "This is a benchtop function/arbitrary waveform generator used to produce controlled test signals such as sine waves, with support for triggering and burst-style output. It is commonly used for electronic circuit testing, instrument synchronization, stimulus injection, and general laboratory signal-source tasks.",
  "tag_hints": [
    "function generator",
    "arbitrary waveform generator",
    "signal source",
    "burst mode",
    "triggered output",
    "electronic test equipment",
    "Agilent 33210A"
  ],
  "actions": [
    {
      "action_name": "auto-send",
      "description": "向波形发生器发送原始控制命令。",
      "description_en": "Send a raw control command to the waveform generator."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发波形发生器开始一次触发输出或突发输出。",
      "description_en": "Trigger the waveform generator to start a triggered or burst output."
    },
    {
      "action_name": "auto-beep",
      "description": "让仪器发出蜂鸣提示音。",
      "description_en": "Make the instrument emit a beep."
    },
    {
      "action_name": "auto-config",
      "description": "设置输出波形的频率、幅度和波形类型。",
      "description_en": "Configure the output waveform frequency, amplitude, and shape."
    },
    {
      "action_name": "auto-config_burst",
      "description": "设置突发输出模式的循环次数。",
      "description_en": "Configure the burst mode cycle count."
    },
    {
      "action_name": "auto-config_free_running_burst",
      "description": "设置自由运行突发输出的循环次数和重复速率。",
      "description_en": "Configure the free-running burst output cycle count and repetition rate."
    }
  ]
}

